<template>
  <main class="sign-in-page"><section class="sign-in-intro"><router-link to="/" class="intro-brand"><span><i class="fa-solid fa-calendar-check"></i></span><strong>Dienstplan</strong></router-link><div class="intro-copy"><p>Einfach organisiert</p><h1>Dein Dienst.<br><em>Ein Ort.</em></h1><span>Behalte Schichten, Anträge und wichtige Informationen immer im Blick.</span></div><div class="intro-dots"><i></i><i></i><i></i></div></section><section class="sign-in-content"><div class="sign-in-card"><div class="card-heading"><span class="mobile-logo"><i class="fa-solid fa-calendar-check"></i></span><p>Willkommen zurück</p><h2>Anmelden</h2><span>Gib deine Zugangsdaten ein, um fortzufahren.</span></div><p v-if="errorMessage" class="error" role="alert"><i class="fa-solid fa-circle-exclamation"></i>{{ errorMessage }}</p><form @submit.prevent="handleLogin"><label><span>E-Mail-Adresse</span><div><i class="fa-regular fa-envelope"></i><input v-model.trim="email" type="email" autocomplete="email" placeholder="name@beispiel.at" required></div></label><label><span>Passwort</span><div><i class="fa-solid fa-lock"></i><input v-model="password" :type="showPassword ? 'text' : 'password'" autocomplete="current-password" placeholder="••••••••" required><button type="button" :aria-label="showPassword ? 'Passwort ausblenden' : 'Passwort anzeigen'" @click="showPassword = !showPassword"><i class="fa-solid" :class="showPassword ? 'fa-eye-slash' : 'fa-eye'"></i></button></div></label><button class="login-button" type="submit" :disabled="isLoading"><i class="fa-solid" :class="isLoading ? 'fa-spinner fa-spin' : 'fa-arrow-right'"></i>{{ isLoading ? 'Wird angemeldet …' : 'Anmelden' }}</button></form><router-link to="/kontakt" class="help-link"><i class="fa-regular fa-circle-question"></i>Zugangsdaten vergessen?</router-link></div></section></main>
</template>

<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { supabase } from '../config/supabase.js'

const router = useRouter()
const email = ref('')
const password = ref('')
const showPassword = ref(false)
const isLoading = ref(false)
const errorMessage = ref('')

const handleLogin = async () => {
  errorMessage.value = ''; isLoading.value = true
  try {
    const { error } = await supabase.auth.signInWithPassword({ email: email.value, password: password.value })
    if (error) throw error
    const redirect = router.currentRoute.value.query.redirect
    router.replace(typeof redirect === 'string' && redirect.startsWith('/') ? redirect : '/home')
  } catch (error) { errorMessage.value = error?.message === 'Email not confirmed' ? 'Bitte bestätige zuerst deine E-Mail-Adresse.' : 'E-Mail oder Passwort ist nicht korrekt.' } finally { isLoading.value = false }
}
</script>

<style scoped>
