,99,235,.1), transparent 23rem); }.sign-in-card { width: min(100%, 410px); }.card-heading p { margin: 0 0 8px; color: #93c5fd; font-size: .72rem; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }.card-heading h2 { margin: 0; color: #f8fafc; font-size: 2rem; letter-spacing: -.05em; }.card-heading > span { display: block; margin-top: 10px; color: var(--text-secondary); font-size: .87rem; }.mobile-logo { display: none; margin-bottom: 22px; color: #dbeafe; background: #1e40af; }.error { display: flex; align-items: center; gap: 8px; margin: 24px 0 0; padding: 11px 12px; border-radius: 10px; color: #fecdd3; background: rgba(244,63,94,.12); font-size: .8rem; }form { display: grid; gap: 18px; margin-top: 30px; }label { display: grid; gap: 8px; color: #cbd5e1; font-size: .77rem; font-weight: 700; }label > div { position: relative; display: flex; align-items: center; }label > div > i { position: absolute; left: 13px; color: #71809b; font-size: .85rem; }input { width: 100%; height: 47px; padding: 0 43px; border: 1px solid var(--line-strong); border-radius: 11px; outline: 0; color: #e2e8f0; background: #0d192b; font-size: .9rem; transition: .15s ease; }input:focus { border-color: #60a5fa; box-shadow: 0 0 0 3px rgba(59,130,246,.14); }label button { position: absolute; right: 6px; width: 35px; height: 35px; border: 0; border-radius: 8px; color: #8ca0c0; background: transparent; cursor: pointer; }.login-button { min-height: 48px; display: inline-flex; align-items: center; justify-content: center; gap: 9px; margin-top: 6px; border: 0; border-radius: 11px; color: #fff; background: linear-gradient(135deg,#2563eb,#3b82f6); box-shadow: 0 12px 22px rgba(37,99,235,.25); font-size: .86rem; font-weight: 800; cursor: pointer; }.login-button:hover { filter: brightness(1.07); }.login-button:disabled { opacity: .65; cursor: wait; }.help-link { display: flex; justify-content: center; align-items: center; gap: 7px; margin-top: 22px; color: #93c5fd; font-size: .78rem; text-decoration: none; }.help-link:hover { color: #dbeafe; }
@media (max-width: 760px) { .sign-in-page { grid-template-columns: 1fr; }.sign-in-intro { min-height: 210px; padding: 24px; }.intro-copy { margin-top: auto; }.intro-copy h1, .intro-copy > span, .intro-dots { display: none; }.sign-in-content { align-items: start; min-height: calc(100vh - 210px); padding: 42px 22px; }.mobile-logo { display: grid; }.sign-in-card { width: min(100%, 440px); } }
</style>
